/** Pure byte formatting; no TypeScript, source catalog, adapter or filesystem import. */
const { createHash } = require("node:crypto");
const sha256 = value => createHash("sha256").update(value).digest("hex");
const GENERATED_METADATA_FACADE_V3 = "src/modules/moduleMetadataV2.generated.ts";
const GENERATED_METADATA_DATA_V3 = "src/modules/moduleMetadataV2.data.json";

function renderGeneratedModuleMetadataV3(metadata, constants) {
  const data = JSON.stringify({ schema: "editkin.module-metadata-data/v3", metadata, constants }, null, 2) + "\n";
  const text = [
    "// Generated by scripts/refresh-module-metadata-v2.cjs; do not edit.",
    `// Registry data SHA-256: ${sha256(data)}`,
    'import data from "./moduleMetadataV2.data.json";',
    'import type { ModuleManifest, ModuleKind, ModuleStatus, ModuleFormat } from "./moduleTypes";',
    'import type { ModuleRegistryIdentityV2 } from "./moduleMetadataRuntimeV2";',
    "type Metadata = {",
    "  identity: ModuleRegistryIdentityV2;",
    "  manifests: ModuleManifest[];",
    "};",
    "type Constants = {",
    "  registrySchema: \"editkin.module-registry-identity/v1\";",
    "  moduleSchema: \"editkin.module/v1\";",
    "  indexSchema: \"editkin.module-index/v1\";",
    "  kinds: readonly ModuleKind[];",
    "  statuses: readonly ModuleStatus[];",
    "  formats: readonly ModuleFormat[];",
    "};",
    "export const moduleMetadataV2: Metadata = data.metadata as unknown as Metadata;",
    "export const moduleMetadataConstantsV2: Constants = data.constants as unknown as Constants;",
    "",
  ].join("\n");
  return { text, data };
}

function generatedModuleMetadataIdentitiesV3({ text, data }) {
  if (typeof text !== "string" || typeof data !== "string") throw Error("MODULE_METADATA_GENERATED_BYTES_REQUIRED");
  return [
    { file: GENERATED_METADATA_FACADE_V3, bytes: Buffer.byteLength(text), sha256: sha256(text) },
    { file: GENERATED_METADATA_DATA_V3, bytes: Buffer.byteLength(data), sha256: sha256(data) },
  ];
}

function checkGeneratedModuleMetadataV3(expected, actual) {
  if (typeof expected.data !== "string" || typeof actual.data !== "string" || expected.data !== actual.data
    || expected.text !== actual.text || expected.binding !== actual.binding) {
    throw Error("MODULE_METADATA_STALE: generated facade/data/source binding changed; refresh and review before building");
  }
  return true;
}

module.exports = { renderGeneratedModuleMetadataV3, generatedModuleMetadataIdentitiesV3, checkGeneratedModuleMetadataV3,
  GENERATED_METADATA_FACADE_V3, GENERATED_METADATA_DATA_V3 };
